INSERT INTO project_version (
    project_id, version_number, source_type, source_file_name, source_storage_ref,
    source_content_hash, status, total_file_count, parsed_file_count, excluded_file_count,
    failed_file_count, total_size_bytes, created_at, updated_at
) VALUES (
    #{projectId}, #{versionNumber}, #{sourceType}, #{sourceFileName}, #{sourceStorageRef},
    #{sourceContentHash}, #{status}, #{totalFileCount}, #{parsedFileCount}, #{excludedFileCount},
    #{failedFileCount}, #{totalSizeBytes}, #{createdAt}, #{updatedAt}
)

