UPDATE project_version
SET knowledge_build_status = 'BUILDING',
    knowledge_build_attempts = knowledge_build_attempts + 1,
    knowledge_build_error = NULL,
    updated_at = #{updatedAt}
WHERE id = #{versionId}
  AND knowledge_build_status IN

    #{fromStatus}

UPDATE project_version
SET knowledge_build_status = 'FAILED',
    knowledge_build_error = #{error},
    updated_at = #{updatedAt}
WHERE id = #{versionId}

